# Databricks notebook source
# MAGIC %md
# MAGIC # Identity Datalake — Phase 0 Tables
# MAGIC
# MAGIC Canonical identity spine: canonical identities, typed personas, provider
# MAGIC cross-references (with mapping history), the append-only resolution decision
# MAGIC log, steward decisions, merge/split impact, identity findings, ownership
# MAGIC relations and per-source health. IDs are generated by writers (no column
# MAGIC defaults). Idempotent: safe to re-run.

# COMMAND ----------

dbutils.widgets.text("catalog", "soc_platform", "Unity Catalog Name")
dbutils.widgets.text("schema", "agentic_soc", "Schema Name")

catalog = dbutils.widgets.get("catalog")
schema = dbutils.widgets.get("schema")

spark.sql(f"USE CATALOG `{catalog}`")
spark.sql(f"USE SCHEMA `{schema}`")

TBL = "USING DELTA TBLPROPERTIES ('delta.enableChangeDataFeed' = 'true', 'delta.autoOptimize.optimizeWrite' = 'true')"

# COMMAND ----------

